package dev.industrialtechnology.solar;
import java.util.*;import net.minecraft.world.World;import net.minecraft.tileentity.TileEntity;import net.minecraftforge.common.util.ForgeDirection;import net.minecraftforge.event.world.*;import cpw.mods.fml.common.eventhandler.SubscribeEvent;import cpw.mods.fml.common.gameevent.TickEvent;import dev.industrialtechnology.capacitor.BankLedger;import dev.industrialtechnology.expansion.ExpansionConfig;import cofh.api.energy.IEnergyReceiver;
/** Loaded panels form cached horizontal components. Physical cells retain RF across topology changes. */
public final class SolarArrays {
 private static final Map<World,SolarArrays> worlds=new IdentityHashMap<>();private final Set<TileSolar> tiles=Collections.newSetFromMap(new IdentityHashMap<TileSolar,Boolean>());private final List<Array> arrays=new ArrayList<>();private boolean dirty=true;private final World world;
 public SolarArrays(){world=null;}private SolarArrays(World w){world=w;}private static SolarArrays of(World w){SolarArrays a=worlds.get(w);if(a==null){a=new SolarArrays(w);worlds.put(w,a);}return a;}
 public static void attach(TileSolar t){of(t.getWorldObj()).tiles.add(t);dirty(t.getWorldObj());}public static void detach(TileSolar t){SolarArrays a=worlds.get(t.getWorldObj());if(a!=null){a.tiles.remove(t);a.dirty=true;if(t.array!=null)t.array.valid=false;t.array=null;}}public static void dirty(World w){SolarArrays a=worlds.get(w);if(a!=null){a.dirty=true;for(Array n:a.arrays)n.valid=false;}}
 public static Array network(TileSolar t){SolarArrays a=of(t.getWorldObj());if(!a.tiles.contains(t)){a.tiles.add(t);a.dirty=true;}a.rebuild();Array n=t.array;return n;}
 private String key(int x,int y,int z){return x+":"+y+":"+z;}
 private void rebuild(){if(!dirty)return;for(Array n:arrays)if(n.busy)return;dirty=false;arrays.clear();Map<String,TileSolar> at=new HashMap<>();for(TileSolar t:tiles)if(!t.isInvalid()&&world.getChunkProvider().chunkExists(t.xCoord>>4,t.zCoord>>4))at.put(key(t.xCoord,t.yCoord,t.zCoord),t);Set<TileSolar> seen=Collections.newSetFromMap(new IdentityHashMap<TileSolar,Boolean>());for(TileSolar root:at.values()){if(seen.contains(root))continue;List<TileSolar> list=new ArrayList<>();ArrayDeque<TileSolar> q=new ArrayDeque<>();q.add(root);seen.add(root);while(!q.isEmpty()){TileSolar t=q.remove();list.add(t);for(ForgeDirection d:ForgeDirection.VALID_DIRECTIONS)if(d.offsetY==0){TileSolar next=at.get(key(t.xCoord+d.offsetX,t.yCoord,t.zCoord+d.offsetZ));if(next!=null&&!seen.contains(next)&&(ExpansionConfig.mixed||next.tier()==root.tier())&&seenSize(list,q)<ExpansionConfig.maxArray){seen.add(next);q.add(next);}}}Array n=new Array(list,world);arrays.add(n);for(TileSolar t:list)t.array=n;}}
 private int seenSize(List<?> l,Collection<?> q){return l.size()+q.size();}
 public static final class Array {
  public final List<TileSolar> members;public final BankLedger ledger;public final long limit;public long generation;public boolean busy,valid=true;private long at=Long.MIN_VALUE;private final World world;private final List<Port> ports=new ArrayList<>();private int cursor;
  Array(List<TileSolar> list,World w){world=w;members=list;List<BankLedger.Cell> cells=new ArrayList<>();long rate=0;int peak=0;for(TileSolar t:list){cells.add(t.cell());rate+=t.rate();peak=Math.max(peak,t.rate());for(ForgeDirection d:ForgeDirection.VALID_DIRECTIONS)if(d!=ForgeDirection.UP&&w.getChunkProvider().chunkExists((t.xCoord+d.offsetX)>>4,(t.zCoord+d.offsetZ)>>4)){TileEntity other=w.getTileEntity(t.xCoord+d.offsetX,t.yCoord+d.offsetY,t.zCoord+d.offsetZ);if(other instanceof IEnergyReceiver)ports.add(new Port(other,d.getOpposite()));}}limit=rate;ledger=new BankLedger(cells,peak,peak);}
  void generate(){if(!valid||busy)return;long now=world.getTotalWorldTime();if(at==now)return;at=now;generation=0;for(TileSolar t:members){t.generated=(int)Math.floor(t.rate()*t.sun());generation+=t.generated;if(t.generatedAt!=now){t.generatedAt=now;ledger.receive(t.generated,now,-1,false);}}}
  void output(){generate();if(!valid||busy||ports.isEmpty())return;busy=true;try{for(int i=0;i<ports.size();i++){Port p=ports.get((cursor+i)%ports.size());if(p.tile.isInvalid())continue;int available=ledger.extract(Integer.MAX_VALUE,world.getTotalWorldTime(),limit,true);if(available<=0)break;BankLedger.Reservation r=ledger.reserveOutput(available,world.getTotalWorldTime(),limit);int accepted=r.amount;try{accepted=Math.max(0,Math.min(r.amount,((IEnergyReceiver)p.tile).receiveEnergy(p.side,r.amount,false)));}catch(RuntimeException e){dev.industrialtechnology.core.IndustrialTechnology.log.warn("Solar receiver failed; conservatively charged offered RF",e);}r.settle(accepted);}}finally{cursor=(cursor+1)%ports.size();busy=false;}}
 }
 private static final class Port{final TileEntity tile;final ForgeDirection side;Port(TileEntity t,ForgeDirection d){tile=t;side=d;}}
 @SubscribeEvent public void tick(TickEvent.WorldTickEvent e){if(e.phase==TickEvent.Phase.END&&!e.world.isRemote){SolarArrays a=worlds.get(e.world);if(a!=null){a.rebuild();for(Array n:new ArrayList<>(a.arrays))n.output();}}}
 @SubscribeEvent public void unload(WorldEvent.Unload e){worlds.remove(e.world);}@SubscribeEvent public void load(ChunkEvent.Load e){if(e.world.isRemote)return;for(Object t:e.getChunk().chunkTileEntityMap.values())if(t instanceof TileSolar)attach((TileSolar)t);dirty(e.world);}@SubscribeEvent public void unloadChunk(ChunkEvent.Unload e){if(e.world.isRemote)return;for(Object t:e.getChunk().chunkTileEntityMap.values())if(t instanceof TileSolar)detach((TileSolar)t);dirty(e.world);}public static void clear(){worlds.clear();}
}
